 deadly:{name:'Children’s Health Queensland — formas de otite e repercussões auditivas',url:'https://www.childrens.health.qld.gov.au/our-work/deadly-ears/health-professionals'},
 ear:{name:'NHS — infecções do ouvido e cuidados',url:'https://www.nhs.uk/conditions/ear-infections/'},
 perforation:{name:'NHS — tímpano perfurado',url:'https://www.nhs.uk/conditions/perforated-eardrum/'},
